Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -20,4 +20,30 @@
 <section class="card event-card"><div class="card-title"><span>CATATAN</span><span>LOG</span></div><div class="event-copy" id="log"><strong>Jalan panjang menanti.</strong>Nyalakan mesin dan cari apa pun yang bisa menyelamatkanmu.</div><span class="event-pill" id="statusPill">MESIN MATI</span></section></aside></main>
 <footer class="bottom"><div class="hint" id="hint">WASD / ← → untuk menyetir · SPASI menembak · R untuk mulai</div><div class="controls"><button class="action" id="leftBtn" aria-label="Belok kiri"><span class="ico">◀</span>KIRI</button><button class="action fire" id="fireBtn" aria-label="Tembak"><span class="ico">✹</span>TEMBAK</button><button class="action" id="rightBtn" aria-label="Belok kanan"><span class="ico">▶</span>KANAN</button><button class="action drive" id="driveBtn"><span class="ico">▶</span><span id="driveLabel">NYALAKAN</span></button></div></footer>
 </div>
 <script>
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);
+const game={mode:'title',day:1,distance:0,health:100,fuel:100,hunger:100,thirst:100,food:3,water:3,ammo:12,armor:2,road:0,lane:0,targetLane:0,speed:0,elapsed:0,dayProgress:0,spawnTimer:8,enemy:null,crate:null,shotFlash:0,shake:0,seed:21,mutantWins:0};
+let W=800,H=500,last=0,held={};
+function rand(){game.seed=(game.seed*1664525+1013904223)>>>0;return game.seed/4294967296}
+function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);W=Math.max(1,r.width);H=Math.max(1,r.height);canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0)}
+new ResizeObserver(resize).observe(canvas);resize();
+function showDialog(kind){const o=$('overlay');o.style.display='grid';if(kind==='title'){o.innerHTML='<div class="dialog"><div class="big-icon">🚙</div><div class="eyebrow">SEBUAH PERJALANAN BERTAHAN HIDUP</div><h2>30 hari.<br>Tak ada jalan pulang.</h2><p>Seberangi gurun merah dengan mobil reyotmu. Cari peti, lawan mutan, dan jaga persediaan sampai hari ke-30.</p><div class="dialog-actions"><button class="primary" onclick="startGame()">MULAI PERJALANAN</button><button onclick="howTo()">CARA BERMAIN</button></div></div>'}else if(kind==='help'){o.innerHTML='<div class="dialog"><div class="eyebrow">PANDUAN PENJALAN</div><h2>Tetap bergerak.</h2><p>Belok untuk menghindari mutan dan rintangan. TEMBAK untuk melawan (amunisi terbatas). Tiap hari menguras air, ransum, dan bensin. Peti bisa berisi suplai atau sampah beracun—pilih dengan bijak.</p><div class="dialog-actions"><button class="primary" onclick="showDialog(\'title\')">MENGERTI</button></div></div>'}else if(kind==='crate'){o.innerHTML='<div class="dialog"><div class="big-icon">📦</div><div class="eyebrow">PETI DI TEPI JALAN</div><h2>Periksa isinya?</h2><p>Debu menutupi tanda peringatan. Mungkin perbekalan… mungkin sesuatu yang seharusnya tetap terkubur.</p><div class="dialog-actions"><button class="primary" onclick="openCrate(true)">BUKA PETI</button><button onclick="openCrate(false)">LEWATI SAJA</button></div></div>'}else if(kind==='loot'){o.innerHTML=`<div class="dialog"><div class="big-icon">${game.crate?.icon||'📦'}</div><div class="eyebrow">ISI PETI</div><h2>${game.crate?.title||'Temuan'}</h2><p>${game.crate?.text||''}</p><p class="loot">${game.crate?.result||''}</p><div class="dialog-actions"><button class="primary" onclick="closeEvent()">LANJUTKAN</button></div></div>`}else if(kind==='gameover'||kind==='win'){const win=kind==='win';o.innerHTML=`<div class="dialog"><div class="big-icon">${win?'🌅':'☠️'}</div><div class="eyebrow">${win?'KAMU BERHASIL':'PERJALANAN BERAKHIR'}</div><h2>${win?'Hari ke-30. Kamu selamat.':'Gurun mengambil semuanya.'}</h2><p>${win?'Mesin batuk untuk terakhir kali di ujung gurun. Kamu berhasil bertahan hidup.':'Kamu bertahan sampai hari '+game.day+'. Setiap kilometer adalah perjuangan.'} Jarak ditempuh: ${Math.floor(game.distance)} km.</p><div class="dialog-actions"><button class="primary" onclick="location.reload()">COBA LAGI</button></div></div>`}else o.innerHTML=''}
+function hideDialog(){$('overlay').style.display='none'}
+function startGame(){hideDialog();game.mode='drive';game.speed=55;game.dayProgress=0;updateHUD();$('statusPill').textContent='MELAJU';log('Mesin menyala. Semoga cukup bensin sampai besok.');$('hint').textContent='WASD / ← → untuk menyetir · SPASI menembak · TEMBAK untuk melawan'}
+function howTo(){showDialog('help')}
+function log(head,text){$('log').innerHTML=`<strong>${head}</strong>${text}`}
+function toast(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
+function updateHUD(){for(const key of ['health','fuel','hunger','thirst']){const v=Math.max(0,Math.min(100,Math.round(game[key])));$(key+'Num').textContent=v;const b=$(key+'Bar');b.style.width=v+'%';b.className='fill'+(v<25?' low':v<50?' warn':'')}
+for(const key of ['food','water','ammo','armor'])$(key+'Num').textContent=game[key];$('dayBadge').innerHTML=`HARI ${String(game.day).padStart(2,'0')} <span style="color:#798775">/ 30</span>`;$('distance').textContent=String(Math.floor(game.distance)).padStart(3,'0');$('sector').textContent=String(Math.ceil(game.distance/30)+1).padStart(2,'0')}
+function consumeDay(){game.day++;game.hunger-=14;game.thirst-=18;game.fuel-=9;if(game.food>0){game.food--;game.hunger=Math.min(100,game.hunger+20)}if(game.water>0){game.water--;game.thirst=Math.min(100,game.thirst+25)}if(game.hunger<=0)game.health-=12;if(game.thirst<=0)game.health-=17;if(game.fuel<=0){game.speed=0;game.health-=4;toast('Bensin habis!');}if(game.health<=0||game.day>30){finish(game.health>0);return}log('Hari '+game.day+' dimulai.','Ransum dan air dikonsumsi. Cari suplai sebelum malam.');toast('HARI '+String(game.day).padStart(2,'0')+' — perjalanan berlanjut');updateHUD()}
+function finish(win){game.mode=win?'win':'gameover';game.speed=0;$('statusPill').textContent=win?'SELAMAT':'TERHENTI';showDialog(win?'win':'gameover')}
+function createCrate(){const types=[
+{icon:'🥫',title:'Peti ransum militer',text:'Kaleng masih tersegel. Labelnya pudar, tapi tampak aman.',result:'+2 ransum, +1 air',apply(){game.food+=2;game.water+=1}},
+{icon:'🔫',title:'Peti perlengkapan',text:'Kotak amunisi dan pelat baja terselip di bawah kain terpal.',result:'+6 amunisi, +1 armor',apply(){game.ammo+=6;game.armor+=1}},
+{icon:'🧃',title:'Peti minuman',text:'Botol-botol berembun di dalam kotak pendingin yang sudah mati.',result:'+3 air',apply(){game.water+=3}},
+{icon:'☣️',title:'Daging terkontaminasi',text:'Bungkusan daging membengkak. Baunya tajam, tapi perutmu keroncongan.',result:'Makan: +20 lapar, −28 kesehatan · Buang: aman',apply(){showDialog('loot');setTimeout(()=>{const box=$('overlay').querySelector('.dialog-actions');if(box)box.innerHTML='<button class="danger" onclick="tainted(true)">MAKAN (BERISIKO)</button><button class="primary" onclick="tainted(false)">BUANG SAJA</button>'},0)}}
+];game.crate=types[Math.floor(rand()*types.length)];game.mode='crate';game.speed=0;$('statusPill').textContent='PETI DITEMUKAN';showDialog('crate')}
+function openCrate(open){if(!open){game.mode='drive';game.speed=52;game.crate=null;hideDialog();log('Kau melewati peti.','Tak semua yang berkilau layak diambil.');return}const c=game.crate;c.apply();if(c.title!=='Daging terkontaminasi'){game.mode='loot';c.result=c.result;showDialog('loot')}else game.mode='loot'}
+function tainted(eat){if(eat){game.hunger=Math.min(100,game.hunger+20);game.health=Math.max(1,game.health-28);toast('Racun! Kesehatan berkurang.')}else toast('Kau membuang daging beracun.');game.mode='loot';hideDialog();game.speed=52;game.mode='drive';game.crate=null;updateHUD();log(eat?'Keputusan buruk.':'Untung kau tak memakannya.','Mesin kembali meraung. Gurun belum selesai.');}
+function closeEvent(){hideDialog();game.crate=null;game.mode='drive';game.speed=55;$('statusPill').textContent='MELAJU';updateHUD();log('Perjalanan berlanjut.','Jaga persediaan dan tetap awas.');}

