function closeEvent(){hideDialog();game.crate=null;game.mode='drive';game.speed=55;$('statusPill').textContent='MELAJU';updateHUD();log('Perjalanan berlanjut.','Jaga persediaan dan tetap awas.');}
function spawnEnemy(){if(game.mode!=='drive'||game.enemy)return;game.enemy={lane:Math.floor(rand()*3)-1,y:-.18,hp:1};game.spawnTimer=11+rand()*9;$('statusPill').textContent='MUTAN TERLIHAT';log('Gerakan di depan!','Mutan gurun mendekat. Hindari atau tembak sebelum menabrak.')}
function shoot(){if(game.mode!=='drive')return;if(game.ammo<1){toast('Amunisi habis!');return}game.ammo--;game.shotFlash=.16;if(game.enemy&&game.enemy.lane===game.lane&&game.enemy.y>.05){game.enemy=null;game.mutantWins++;game.spawnTimer=8+rand()*9;toast('Mutan tumbang!');$('statusPill').textContent='MELAJU';log('Mutan berhasil ditumbangkan.','Kau menghemat sedikit nyawa—dan satu peluru.')}else toast('Tembakan meleset…');updateHUD()}
function steer(dir){if(game.mode!=='drive')return;game.targetLane=Math.max(-1,Math.min(1,game.targetLane+dir))}
function toggleDrive(){if(game.mode==='title'){startGame();return}if(game.mode==='drive'){game.mode='paused';game.speed=0;$('driveLabel').textContent='LANJUT';$('driveBtn').querySelector('.ico').textContent='▶';$('statusPill').textContent='BERHENTI';log('Mesin dimatikan.','Berhenti terlalu lama di gurun bukan ide bagus.')}else if(game.mode==='paused'){game.mode='drive';game.speed=55;$('driveLabel').textContent='BERHENTI';$('driveBtn').querySelector('.ico').textContent='Ⅱ';$('statusPill').textContent='MELAJU'}}
function damage(amount){if(game.armor>0){game.armor--;amount*=.45;toast('Armor menahan serangan!')}else toast('Mobil dihantam!');game.health=Math.max(0,game.health-amount);game.shake=.35;updateHUD();if(game.health<=0)finish(false)}
function update(dt){if(game.mode!=='drive')return;game.elapsed+=dt;game.distance+=game.speed*dt/22;game.dayProgress+=dt;game.road+=dt*game.speed*.007;game.lane+=(game.targetLane-game.lane)*Math.min(1,dt*7);game.shotFlash=Math.max(0,game.shotFlash-dt);game.shake=Math.max(0,game.shake-dt);game.spawnTimer-=dt;
if(game.dayProgress>=12){game.dayProgress-=12;consumeDay();if(game.mode!=='drive')return}
if(game.fuel<=0){game.speed=0;game.fuel=Math.max(0,game.fuel-dt*.3)}
if(!game.enemy&&game.spawnTimer<=0){if(rand()<.7)spawnEnemy();else game.spawnTimer=5}
if(game.enemy){game.enemy.y+=dt*.10;if(game.enemy.y>.76&&Math.abs(game.enemy.lane-game.lane)<.55){damage(18);game.enemy=null;game.spawnTimer=8+rand()*8;$('statusPill').textContent='MELAJU'}else if(game.enemy.y>1.15){game.enemy=null;game.spawnTimer=7+rand()*9}}
if(game.elapsed>(game.nextCrate||15)){game.nextCrate=game.elapsed+18+rand()*13;createCrate();return}
if(Math.floor(game.distance)%12===0&&Math.floor(game.distance)!==game.lastDistance&&game.distance>0){game.lastDistance=Math.floor(game.distance);game.fuel=Math.max(0,game.fuel-.4);}
if(game.elapsed%1<dt)updateHUD()
}
function roadPoint(y){const horizon=H*.37,bottom=H*1.08,t=Math.max(0,Math.min(1,(y-horizon)/(bottom-horizon)));const roadW=(W*.12)+(W*.61)*t;return {x:W*.5,w:roadW,t}}
function draw(){const dpr=Math.min(devicePixelRatio||1,2);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);
const sky=ctx.createLinearGradient(0,0,0,H*.55);sky.addColorStop(0,'#efc477');sky.addColorStop(.7,'#e8ac62');sky.addColorStop(1,'#c9864c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*.55);
// sun and distant mesas
ctx.fillStyle='#ffe0a0';ctx.beginPath();ctx.arc(W*.77,H*.2,Math.min(W,H)*.075,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c98550';ctx.beginPath();ctx.moveTo(0,H*.43);ctx.lineTo(W*.10,H*.30);ctx.lineTo(W*.19,H*.39);ctx.lineTo(W*.31,H*.28);ctx.lineTo(W*.46,H*.43);ctx.lineTo(W*.61,H*.31);ctx.lineTo(W*.78,H*.42);ctx.lineTo(W*.9,H*.32);ctx.lineTo(W,H*.41);ctx.lineTo(W,H*.58);ctx.lineTo(0,H*.58);ctx.fill();
const sand=ctx.createLinearGradient(0,H*.4,0,H);sand.addColorStop(0,'#d99b55');sand.addColorStop(1,'#b9793f');ctx.fillStyle=sand;ctx.fillRect(0,H*.4,W,H*.6);
// wind streaks
for(let i=0;i<18;i++){let yy=(i*67+game.road*29)%(H*.65)+H*.35;let xx=(i*149+Math.sin(i*9)*40)%W;ctx.globalAlpha=.12;ctx.strokeStyle='#ffe0a0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(xx,yy);ctx.lineTo(xx+12+(yy/H)*23,yy);ctx.stroke()}ctx.globalAlpha=1;
// road perspective
const hz=H*.37;ctx.fillStyle='#66584a';ctx.beginPath();ctx.moveTo(W*.43,hz);ctx.lineTo(W*.57,hz);ctx.lineTo(W*1.02,H);ctx.lineTo(-W*.02,H);ctx.closePath();ctx.fill();ctx.fillStyle='#806b55';ctx.beginPath();ctx.moveTo(W*.447,hz);ctx.lineTo(W*.553,hz);ctx.lineTo(W*.91,H);ctx.lineTo(W*.09,H);ctx.closePath();ctx.fill();
// dashed lane stripes
for(let i=0;i<8;i++){const t=((i/8+game.road*.16)%1);const y=hz+(H-hz)*t;const p=roadPoint(y);const dash=5+26*t;ctx.fillStyle='#d5b886';for(let lane=-1;lane<=1;lane+=2){ctx.fillRect(p.x+lane*p.w*.33-dash*.07,y,dash*.14,dash)}}
// roadside stones and cacti
for(let i=0;i<11;i++){let t=((i/11+game.road*.055)%1),y=hz+(H-hz)*t,p=roadPoint(y),size=3+16*t;let side=i%2?1:-1,x=p.x+side*(p.w*.55+size*2);ctx.fillStyle=i%3?'#76553c':'#59704c';if(i%3){ctx.beginPath();ctx.ellipse(x,y,size,size*.45,0,0,Math.PI*2);ctx.fill()}else{ctx.fillRect(x-size*.2,y-size,size*.4,size);ctx.fillRect(x-size,y-size*.5,size*.35,size*.5);ctx.fillRect(x+size*.2,y-size*.7,size*.35,size*.5)}}
// road debris decorative truck? crate and monster
if(game.enemy){const e=game.enemy,p=roadPoint(Math.max(hz,Math.min(H,e.y*H)));const x=p.x+e.lane*p.w*.31,s=15+p.t*33;ctx.fillStyle='#4b322d';ctx.beginPath();ctx.ellipse(x,p.y,s*.65,s*.28,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#53654a';ctx.beginPath();ctx.moveTo(x-s*.43,p.y);ctx.lineTo(x-s*.25,p.y-s*.9);ctx.lineTo(x+s*.18,p.y-s*.83);ctx.lineTo(x+s*.42,p.y);ctx.closePath();ctx.fill();ctx.fillStyle='#d9bb75';ctx.fillRect(x-s*.18,p.y-s*.53,s*.12,s*.1);ctx.fillRect(x+s*.11,p.y-s*.5,s*.1,s*.1);ctx.fillStyle='#aa5745';ctx.fillRect(x-s*.15,p.y-s*.14,s*.32,s*.08)}
// player car
const carX=W*.5+game.lane*(W*.115),carY=H*.79,carW=Math.min(W*.15,82),carH=carW*.6;ctx.save();if(game.shake)ctx.translate((rand()-.5)*game.shake*12,(rand()-.5)*game.shake*8);ctx.fillStyle='#523c2c';ctx.beginPath();ctx.ellipse(carX,carY+carH*.4,carW*.7,carH*.32,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#283638';ctx.fillRect(carX-carW*.55,carY-carH*.27,carW*.18,carH*.3);ctx.fillRect(carX+carW*.37,carY-carH*.27,carW*.18,carH*.3);ctx.fillStyle='#d97842';ctx.beginPath();ctx.roundRect(carX-carW*.48,carY-carH*.42,carW*.96,carH*.8,carW*.18);ctx.fill();ctx.fillStyle='#f0bd73';ctx.beginPath();ctx.roundRect(carX-carW*.31,carY-carH*.39,carW*.62,carH*.34,5);ctx.fill();ctx.fillStyle='#4c5752';ctx.fillRect(carX-carW*.27,carY-carH*.34,carW*.54,carH*.24);ctx.fillStyle='#f8d591';ctx.fillRect(carX-carW*.38,carY+carH*.19,carW*.16,carH*.08);ctx.fillRect(carX+carW*.22,carY+carH*.19,carW*.16,carH*.08);ctx.fillStyle='#554433';ctx.fillRect(carX-carW*.12,carY-carH*.49,carW*.24,carH*.1);if(game.shotFlash){ctx.fillStyle='#fff0a1';ctx.beginPath();ctx.moveTo(carX,carY-carH*.62);ctx.lineTo(carX-8,carY-carH*1.1);ctx.lineTo(carX,carY-carH*1.4);ctx.lineTo(carX+8,carY-carH*1.1);ctx.fill()}ctx.restore();
// lower frame vignette
const vg=ctx.createLinearGradient(0,0,0,H);vg.addColorStop(0,'#111a1c00');vg.addColorStop(1,'#111a1c33');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);
}

